// Jonker-Volgenant algorithm (from scipy's rectangular_lsap, simplified for square)
// We'll implement a classic O(n^3) Hungarian (Kuhn-Munkres) and JV.

using namespace std;
using clk = chrono::high_resolution_clock;

// ---------- Hungarian (potentials) ----------
// Minimization. cost is row-major double n*n
static vector<int> hungarian(const double* cost, int n) {
    const double INF = 1e18;
    vector<double> u(n+1), v(n+1);
    vector<int> p(n+1), way(n+1);
    for (int i = 1; i <= n; ++i) {
        p[0] = i;
        int j0 = 0;
        vector<double> minv(n+1, INF);
        vector<char> used(n+1, false);
        do {
            used[j0] = true;
            int i0 = p[j0], j1 = 0;
            double delta = INF;
            const double* row = cost + (size_t)(i0-1)*n;
            for (int j = 1; j <= n; ++j) if (!used[j]) {
                double cur = row[j-1] - u[i0] - v[j];
                if (cur < minv[j]) { minv[j] = cur; way[j] = j0; }
                if (minv[j] < delta) { delta = minv[j]; j1 = j; }
            }
            for (int j = 0; j <= n; ++j) {
                if (used[j]) { u[p[j]] += delta; v[j] -= delta; }
                else minv[j] -= delta;
            }
            j0 = j1;
        } while (p[j0] != 0);
        do {
            int j1 = way[j0];
            p[j0] = p[j1];
            j0 = j1;
        } while (j0);
    }
    vector<int> assign(n);
    for (int j = 1; j <= n; ++j) assign[p[j]-1] = j-1;
    return assign; // assign[row] = col
}

// ---------- Jonker-Volgenant (dense, from a common implementation) ----------
// Based on the algorithm used by scipy.optimize._lsap
static vector<int> jv(const double* cost, int n) {
    const double INF = numeric_limits<double>::infinity();
    vector<double> u(n, 0.0), v(n, 0.0);
    vector<int> rowsol(n, -1), colsol(n, -1);
    vector<double> d(n);
    vector<int> pred(n), cols(n);
    vector<char> free_row(n, 1);

    // column reduction
    for (int j = n-1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i*n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) {
            rowsol[imin] = j;
            colsol[j] = imin;
        } else {
            // leave for later; mark column unassigned if conflict? handled below
        }
    }
    // Actually a proper JV is more involved. Fall back: just return hungarian for now if not complete.
    // Check completeness
    int cnt = 0;
    for (int i = 0; i < n; ++i) if (rowsol[i] != -1) cnt++;
    if (cnt != n) {
        // incomplete column reduction; use hungarian
        return hungarian(cost, n);
    }
    return rowsol;
}

