#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <vector>
#include <chrono>
#include <cstdint>
#include <algorithm>
using namespace std;
using clk = chrono::high_resolution_clock;

// JV with decrease-key binary heap
static void jv(const double* cost, int n, int* rowsol_out) {
    const double INF = 1e18;
    vector<double> v(n, 0.0);
    vector<int> rowsol(n, -1), colsol(n, -1);

    for (int j = n - 1; j >= 0; --j) {
        double minv = cost[j];
        int imin = 0;
        for (int i = 1; i < n; ++i) {
            double c = cost[(size_t)i * n + j];
            if (c < minv) { minv = c; imin = i; }
        }
        v[j] = minv;
        if (rowsol[imin] == -1) { rowsol[imin] = j; colsol[j] = imin; }
    }

    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < n; ++i) {
            if (rowsol[i] != -1) continue;
            double umin = INF, usub = INF;
            int jmin = -1, jsub = -1;
            const double* row = cost + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                double h = row[j] - v[j];
                if (h < usub) {
                    if (h >= umin) { usub = h; jsub = j; }
                    else { usub = umin; umin = h; jsub = jmin; jmin = j; }
                }
            }
            int j1 = jmin;
            int i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 != -1) { j1 = jsub; i0 = colsol[j1]; }
            if (i0 != -1) {
                if (umin < usub) rowsol[i0] = -1;
                else continue;
            }
            rowsol[i] = j1;
            colsol[j1] = i;
        }
    }

    vector<double> heap_key(n + 2), d(n);
    vector<int> heap_col(n + 2), pos(n), pred(n);
    vector<char> scanned(n);

    for (int f = 0; f < n; ++f) {
        if (rowsol[f] != -1) continue;
        const double* frow = cost + (size_t)f * n;
        for (int j = 0; j < n; ++j) {
            d[j] = frow[j] - v[j];
            pred[j] = f;
            scanned[j] = 0;
            heap_key[j + 1] = d[j];
            heap_col[j + 1] = j;
            pos[j] = j + 1;
        }
        int hsz = n;
        for (int k0 = hsz / 2; k0 >= 1; --k0) {
            int k = k0;
            while (true) {
                int left = k << 1;
                if (left > hsz) break;
                int right = left + 1;
                int smallest = left;
                if (right <= hsz && heap_key[right] < heap_key[left]) smallest = right;
                if (heap_key[k] <= heap_key[smallest]) break;
                swap(heap_key[k], heap_key[smallest]);
                swap(heap_col[k], heap_col[smallest]);
                pos[heap_col[k]] = k;
                pos[heap_col[smallest]] = smallest;
                k = smallest;
            }
        }
        while (true) {
            int jmin = heap_col[1];
            double mind = heap_key[1];
            --hsz;
            if (hsz > 0) {
                heap_key[1] = heap_key[hsz + 1];
                heap_col[1] = heap_col[hsz + 1];
                pos[heap_col[1]] = 1;
                int k = 1;
                while (true) {
                    int left = k << 1;
                    if (left > hsz) break;
                    int right = left + 1;
                    int smallest = left;
                    if (right <= hsz && heap_key[right] < heap_key[left]) smallest = right;
                    if (heap_key[k] <= heap_key[smallest]) break;
                    swap(heap_key[k], heap_key[smallest]);
                    swap(heap_col[k], heap_col[smallest]);
                    pos[heap_col[k]] = k;
                    pos[heap_col[smallest]] = smallest;
                    k = smallest;
                }
            }
            pos[jmin] = -1;
            scanned[jmin] = 1;
            int i0 = colsol[jmin];
            if (i0 == -1) {
                int jcur = jmin;
                while (true) {
                    int ip = pred[jcur];
                    int jnext = rowsol[ip];
                    colsol[jcur] = ip;
                    rowsol[ip] = jcur;
                    if (ip == f) break;
                    jcur = jnext;
                }
                for (int j = 0; j < n; ++j)
                    if (scanned[j]) v[j] += d[j] - mind;
                break;
            }
            const double* irow = cost + (size_t)i0 * n;
            double base = irow[jmin] - v[jmin];
            for (int j = 0; j < n; ++j) {
                int pj = pos[j];
                if (pj == -1) continue;
                double nd = irow[j] - v[j] - base + mind;
                if (nd < d[j]) {
                    d[j] = nd;
                    pred[j] = i0;
                    heap_key[pj] = nd;
                    int k = pj;
                    while (k > 1) {
                        int par = k >> 1;
                        if (heap_key[par] <= heap_key[k]) break;
                        swap(heap_key[par], heap_key[k]);
                        swap(heap_col[par], heap_col[k]);
                        pos[heap_col[par]] = par;
                        pos[heap_col[k]] = k;
                        k = par;
                    }
                }
            }
        }
    }
    for (int i = 0; i < n; ++i) rowsol_out[i] = rowsol[i];
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 600;
    int reps = argc > 2 ? atoi(argv[2]) : 3;
    srand(1);
    vector<double> sx(n), sy(n), tx(n), ty(n);
    for (int i = 0; i < n; ++i) {
        sx[i] = rand()/(double)RAND_MAX; sy[i] = rand()/(double)RAND_MAX;
        tx[i] = rand()/(double)RAND_MAX; ty[i] = rand()/(double)RAND_MAX;
    }
    vector<double> cost((size_t)n*n);
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < n; ++j) {
            double dx = sx[i]-tx[j], dy = sy[i]-ty[j];
            cost[(size_t)i*n+j] = sqrt(dx*dx+dy*dy);
        }
    vector<int> asg(n);
    jv(cost.data(), n, asg.data());
    auto t0 = clk::now();
    for (int r = 0; r < reps; ++r) jv(cost.data(), n, asg.data());
    auto t1 = clk::now();
    double ms = chrono::duration<double, milli>(t1-t0).count()/reps;
    vector<char> seen(n, 0); bool ok = true;
    for (int i = 0; i < n; ++i) { if (asg[i]<0||asg[i]>=n||seen[asg[i]]) ok=false; seen[asg[i]]=1; }
    printf("jv n=%d time=%.2f ms ok=%d\n", n, ms, (int)ok);
}
