// and also a threshold algorithm.

// ---- auction algorithm (Bertsekas) ----
// epsilon-scaling auction for assignment. For uniform weights the assignment is optimal
// for the exact problem when epsilon < 1/n * min cost gap. With integer-scaled costs
// epsilon = 1/(n+1) guarantees optimality.
static void auction(const double* cost, int n, int* rowsol, double scale) {
    // scale costs to int64
    vector<long long> C((size_t)n*n);
    for (size_t k = 0; k < (size_t)n*n; ++k) C[k] = (long long)llround(cost[k]*scale);
