    // start epsilon
    long long eps_start = Cmax / 4 + 1;
    for (long long e = eps_start; ; ) {
        // reset assignment for this epsilon phase? auction can continue with prices
        vector<char> assigned_row(n, 0);
        int nassigned = 0;
        for (int j = 0; j < n; ++j) {
            if (owner[j] != -1) { assigned_row[owner[j]] = 1; ++nassigned; }
        }
        vector<int> unassigned;
        for (int i = 0; i < n; ++i) if (!assigned_row[i]) unassigned.push_back(i);
        size_t ptr = 0;
        while (nassigned < n) {
            int i;
            if (ptr < unassigned.size()) i = unassigned[ptr++];
            else break;
            while (true) {
                // find best and second best column for row i
                long long best = LLONG_MIN/4, second = LLONG_MIN/4;
                int jbest = 0;
