                for (int j = 0; j < n; ++j) {
                    long long val = -row[j] - price[j]; // benefit = -cost - price (minimization)
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                }
                long long bid = price[jbest] + (best - second) + e;
                // actually price update: new price = price + (best - second) + eps
                // but best = -cost - price, so best - second = (price_second_obj - price_best_obj)
                int prev = owner[jbest];
                price[jbest] = price[jbest] + (best - second) + e;
                owner[jbest] = i;
                if (prev == -1) { ++nassigned; break; }
                else { i = prev; } // displaced, reassign
            }
