#include <cstdio>
#include <vector>
#include <cstdint>
#include <algorithm>
#include <climits>
using namespace std;

// Bertsekas auction for the MINIMIZATION assignment problem, integer costs.
// Person i bids for the object j with highest profit = -C[i,j] - price[j].
// price[j] := -C[i,j] - w_second + eps, where w_second is the second best profit.
// This is the standard "price = best_value_complement + eps" update.
static void auction(const double* cost, int n, int* rowsol, double scale) {
    vector<long long> C((size_t)n * n);
    for (size_t k = 0; k < (size_t)n * n; ++k)
        C[k] = (long long)llround(cost[k] * scale);

    vector<long long> price(n, 0);
    vector<int> owner(n, -1);

    long long Cmax = 1;
    for (auto c : C) if (c > Cmax) Cmax = c;

    for (long long eps = Cmax / 2 + 1; ; eps = max(1LL, (eps * 2) / 5 == eps ? eps - 1 : (eps * 2) / 5)) {
        // fresh assignment each phase, prices carry over (scaled)
        fill(owner.begin(), owner.end(), -1);
        vector<int> unassigned(n);
        for (int i = 0; i < n; ++i) unassigned[i] = i;
        size_t head = 0;
        while (head < unassigned.size()) {
            int i = unassigned[head++];
            const long long* row = C.data() + (size_t)i * n;
            long long best = LLONG_MIN / 4, second = LLONG_MIN / 4;
            int jbest = 0;
            for (int j = 0; j < n; ++j) {
                long long val = -row[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            // bid increment so that best object ties with second: raise price
            // new price makes profit of jbest equal to second - eps
            // -C - new_price = second - eps  => new_price = -C - second + eps
            long long new_price = -row[jbest] - second + eps;
            if (new_price < price[jbest]) new_price = price[jbest]; // monotone
            price[jbest] = new_price;
            int prev = owner[jbest];
            owner[jbest] = i;
            if (prev != -1) unassigned.push_back(prev);
        }
        if (eps == 1) break;
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
}

int main() {
    int n; if (scanf("%d", &n) != 1) return 1;
    vector<double> cost((size_t)n * n);
    for (size_t k = 0; k < (size_t)n * n; ++k) scanf("%lf", &cost[k]);
    vector<int> asg(n, -1);
    auction(cost.data(), n, asg.data(), 1e6);
    for (int i = 0; i < n; ++i) printf("%d\n", asg[i]);
}
