// For each row, keep k nearest columns (by cost). Build CSR.
static void knn_rows(const double* cost, int n, int k, vector<int>& ind, vector<double>& val) {
    ind.resize((size_t)n * k);
    val.resize((size_t)n * k);
    vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        iota(idx.begin(), idx.end(), 0);
        nth_element(idx.begin(), idx.begin() + k, idx.end(), [&](int a, int b){ return row[a] < row[b]; });
        sort(idx.begin(), idx.begin() + k, [&](int a, int b){ return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) {
            ind[(size_t)i * k + t] = idx[t];
            val[(size_t)i * k + t] = row[idx[t]];
        }
    }
}

// Sparse auction on candidate lists. Returns false if it cannot assign everyone
// (candidate graph doesn't admit a matching) — caller should increase k.
static bool auction_sparse(const vector<int>& ind, const vector<double>& val, int n, int k,
                           int* rowsol, double scale) {
    vector<long long> price(n, 0);
    vector<int> owner(n, -1);
    long long Cmax = 1;
    vector<long long> C((size_t)n * k);
    for (size_t t = 0; t < (size_t)n * k; ++t) {
        C[t] = (long long)llround(val[t] * scale);
        if (C[t] > Cmax) Cmax = C[t];
    }
    for (long long eps = Cmax / 2 + 1; ; eps = max(1LL, eps / 4)) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> unassigned(n);
        iota(unassigned.begin(), unassigned.end(), 0);
        size_t head = 0;
        int guard = 0;
        int limit = n * k * 4 + 1000;
        while (head < unassigned.size()) {
            if (++guard > limit) return false;
            int i = unassigned[head++];
            long long best = LLONG_MIN / 4, second = LLONG_MIN / 4;
            int tbest = 0;
            for (int t = 0; t < k; ++t) {
                int j = ind[(size_t)i * k + t];
                long long vprofit = -C[(size_t)i * k + t] - price[j];
                if (vprofit > best) { second = best; best = vprofit; tbest = t; }
                else if (vprofit > second) second = vprofit;
            }
            int jbest = ind[(size_t)i * k + tbest];
            long long new_price = -C[(size_t)i * k + tbest] - second + eps;
            if (new_price < price[jbest]) new_price = price[jbest];
            price[jbest] = new_price;
            int prev = owner[jbest];
            owner[jbest] = i;
            if (prev != -1) unassigned.push_back(prev);
        }
        if (eps == 1) break;
    }
    for (int j = 0; j < n; ++j) {
        if (owner[j] == -1) return false;
        rowsol[owner[j]] = j;
    }
    return true;
}

// Local improvement: while a cheaper alternating swap exists, do it.
// Restricted to each row's k nearest for speed, plus a full check periodically.
static void local_improve(const double* cost, int n, int* asg, int rounds) {
    vector<int> inv(n);
    for (int i = 0; i < n; ++i) inv[asg[i]] = i;
    for (int rd = 0; rd < rounds; ++rd) {
        bool improved = false;
        for (int i = 0; i < n; ++i) {
            int j = asg[i];
            double cij = cost[(size_t)i * n + j];
            for (int j2 = 0; j2 < n; ++j2) {
                if (j2 == j) continue;
                int i2 = inv[j2];
                double delta = cost[(size_t)i * n + j2] + cost[(size_t)i2 * n + j] - cij - cost[(size_t)i2 * n + j2];
                if (delta < -1e-12) {
                    asg[i] = j2; asg[i2] = j;
                    inv[j2] = i; inv[j] = i2;
                    improved = true;
                    j = j2; cij = cost[(size_t)i * n + j];
                }
            }
        }
        if (!improved) break;
    }
}

