// Measure priority-queue Dijkstra SSP (integer) — the JV augmentation with std::priority_queue.
static void ssp_pq(const long long* C, int n, int* rowsol) {
    const long long INF = LLONG_MAX/4;
    vector<long long> v(n, 0);
    vector<int> colsol(n, -1), assign(n, -1);

    for (int j = n-1; j >= 0; --j) {
        long long mn = C[j]; int im = 0;
        for (int i = 1; i < n; ++i) { long long c = C[(size_t)i*n + j]; if (c < mn) { mn = c; im = i; } }
        v[j] = mn;
        if (assign[im] == -1) { assign[im] = j; colsol[j] = im; }
    }
    // augmenting row reduction, 2 passes
    for (int pass = 0; pass < 2; ++pass) {
        for (int i = 0; i < n; ++i) {
            if (assign[i] != -1) continue;
            long long umin = INF, usub = INF; int jmin = -1, jsub = -1;
            const long long* row = C + (size_t)i*n;
            for (int j = 0; j < n; ++j) {
                long long h = row[j] - v[j];
                if (h < usub) { if (h >= umin) { usub = h; jsub = j; } else { usub = umin; umin = h; jsub = jmin; jmin = j; } }
            }
            int j1 = jmin, i0 = colsol[j1];
            if (umin < usub) v[j1] -= (usub - umin);
            else if (i0 != -1) { j1 = jsub; i0 = colsol[j1]; }
            if (i0 != -1) { if (umin < usub) assign[i0] = -1; else continue; }
            assign[i] = j1; colsol[j1] = i;
        }
    }

    vector<long long> dist(n);
    vector<int> pred(n), seen_stamp(n, 0);
    int stamp = 0;
    using P = pair<long long,int>;
    priority_queue<P, vector<P>, greater<P>> pq;

    for (int f = 0; f < n; ++f) {
        if (assign[f] != -1) continue;
        ++stamp;
        pq = priority_queue<P, vector<P>, greater<P>>();
        const long long* frow = C + (size_t)f*n;
        for (int j = 0; j < n; ++j) { dist[j] = frow[j] - v[j]; pred[j] = f; pq.push({dist[j], j}); }
        long long mind = 0; int jmin = -1;
        while (true) {
            auto [dv, j] = pq.top(); pq.pop();
            if (seen_stamp[j] == stamp) continue;
            seen_stamp[j] = stamp;
            mind = dv; jmin = j;
            int i0 = colsol[j];
            if (i0 == -1) break;
            const long long* irow = C + (size_t)i0*n;
            long long base = irow[j] - v[j];
            for (int j2 = 0; j2 < n; ++j2) {
                if (seen_stamp[j2] == stamp) continue;
                long long nd = irow[j2] - v[j2] - base + mind;
                if (nd < dist[j2]) { dist[j2] = nd; pred[j2] = i0; pq.push({nd, j2}); }
            }
        }
        int jcur = jmin;
        while (true) {
            int ip = pred[jcur]; int jnext = assign[ip];
            colsol[jcur] = ip; assign[ip] = jcur;
            if (ip == f) break;
            jcur = jnext;
        }
        for (int j = 0; j < n; ++j) if (seen_stamp[j] == stamp) v[j] += dist[j] - mind;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = assign[i];
}

