// Network simplex for the dense assignment problem (equal supplies 1/n).
// Compact implementation specialized for bipartite assignment with integer costs.
// Based on the standard spanning-tree network simplex (Bonneel / LEMON style),
// simplified: supplies are all +1 (source) and -1 (target) in scaled units,
// so flow is integral and the optimum support is a perfect matching.
#include <cstdio>
#include <cstdlib>
#include <cmath>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <limits>
using namespace std;
using clk = chrono::high_resolution_clock;

struct Node {
    int parent;      // parent node in tree, -1 for root
    int child;       // first child
    int sibling;     // next sibling
    int prev;        // preorder traversal: previous
    int next;        // preorder traversal: next
    long long pot;   // dual potential
    int depth;
    long long flow;  // flow on edge to parent (from parent to this node); sign: positive means parent->node
};

// Nodes: 0..n-1 sources, n..2n-1 targets, 2n root.
// Initial basis: root connected to all sources with flow +1 (root supplies), and
// a diagonal matching source i -> target i with flow 1, targets demand 1.
// We scale so each node has supply/demand 1.

static bool solve(const long long* C, int n, int* match) {
    const int N = 2 * n + 1;
    const int ROOT = 2 * n;
    vector<Node> T(N);
    for (int i = 0; i < N; ++i) {
        T[i].parent = -1; T[i].child = -1; T[i].sibling = -1;
        T[i].prev = -1; T[i].next = -1; T[i].pot = 0; T[i].depth = 0; T[i].flow = 0;
    }
    // Build initial tree: root -> sources (artificial, huge cost), source i -> target i (diagonal).
    // Thread preorder: root, s0, t0, s1, t1, ... using a simple doubly linked order.
    auto link_child = [&](int p, int c) {
        T[c].parent = p;
        T[c].sibling = T[p].child;
        T[p].child = c;
        T[c].depth = T[p].depth + 1;
    };
    // preorder list via next/prev. We'll rebuild preorder after construction with a stack walk.
    for (int i = 0; i < n; ++i) {
        link_child(ROOT, i);          // root -> source i
        T[i].flow = 1;                // root supplies 1 to source
        link_child(i, n + i);         // source i -> target i
        T[n + i].flow = 1;
        T[i].pot = 0;
        T[n + i].pot = -C[(size_t)i * n + i];
    }
    T[ROOT].pot = 0;
    // build preorder doubly-linked list by DFS
    vector<int> order; order.reserve(N);
    vector<int> stack = {ROOT};
    while (!stack.empty()) {
        int u = stack.back(); stack.pop_back();
        order.push_back(u);
        for (int c = T[u].child; c != -1; c = T[c].sibling) stack.push_back(c);
    }
    // The DFS above pushes children in reverse sibling order; preorder is still a valid tree order
    // as long as parent appears before descendants. stack LIFO violates that for siblings but parent
    // is pushed before children, so parent precedes descendants. Good enough for subtree ranges
    // ONLY if we store subtree size. Let's compute subtree ranges via sizes instead of linked order.
    vector<int> subsize(N, 1);
    for (int k = (int)order.size() - 1; k >= 0; --k) {
        int u = order[k];
        if (T[u].parent != -1) subsize[T[u].parent] += subsize[u];
    }
    // preorder position
    vector<int> pos(N);
    for (int k = 0; k < N; ++k) pos[order[k]] = k;

    const long long BIG = (1LL << 60);

    auto reduced = [&](int i, int j) -> long long {
        // arc source i -> target j, cost C[i,j], reduced = C + pot[target] - pot[source]
        return C[(size_t)i * n + j] + T[n + j].pot - T[i].pot;
    };

    auto in_subtree = [&](int node, int anc) -> bool {
        // is node in subtree of anc? using preorder pos and subsize
        return pos[node] >= pos[anc] && pos[node] < pos[anc] + subsize[anc];
    };

    // pivot loop
    long long iter = 0;
    const long long ITERMAX = (long long)n * n * 2;
    while (iter++ < ITERMAX) {
        // find entering arc: most negative reduced cost among forward arcs (source->target)
        // and among backward tree arcs we only enter non-tree arcs.
        int bi = -1, bj = -1; long long best = 0;
        for (int i = 0; i < n; ++i) {
            long long ps = T[i].pot;
            const long long* row = C + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                long long rc = row[j] + T[n + j].pot - ps;
                if (rc < best) { best = rc; bi = i; bj = j; }
            }
        }
        if (bi == -1) break; // optimal

        // augment along cycle: entering arc bi -> n+bj.
        // Find leaving arc: the minimum-flow arc on the path that blocks augmentation.
        // Direction: flow increases on entering arc. Walk from bi and from (n+bj) up to LCA,
        // determine orientation.
        int u = bi, v = n + bj;
        // bring to same depth
        vector<int> up_u, up_v;
        int uu = u, vv = v;
        while (T[uu].depth > T[vv].depth) { up_u.push_back(uu); uu = T[uu].parent; }
        while (T[vv].depth > T[uu].depth) { up_v.push_back(vv); vv = T[vv].parent; }
        while (uu != vv) { up_u.push_back(uu); up_v.push_back(vv); uu = T[uu].parent; vv = T[vv].parent; }
        int lca = uu;
        // Flow of +1 enters at v (target) and leaves at u (source): we send 1 unit from source bi
        // to target bj. On the tree path, edges from u up to lca currently... orientation:
        // Increasing flow on entering arc means: source side path (u -> lca) has flow decreased
        // on edges directed toward lca? Let's reason: the cycle is u -> v ->(tree reverse)-> lca ->(tree)-> u.
        // We add +1 flow on u->v. To balance, we subtract 1 from tree flow along v->lca and add 1 along lca->u,
        // depending on stored orientation.
        // Stored T[x].flow = flow from parent to x. 
        // Path v -> lca: nodes up_v are v, parent(v), ... child of lca. Edge parent(x)->x carries flow T[x].flow
        // from parent to x. Sending flow from v up to lca means flow goes x -> parent, opposite to stored
        // direction, so stored flow decreases. Leaving arc is the one whose stored flow hits 0 first.
        // Since all flows are integral and we send exactly 1, ANY edge on v->lca path with flow==1 can leave;
        // edges with flow>1 just decrement. Initial flows are 1, so the closest such edge leaves.
        // Path lca -> u (down): sending flow from lca down to u increases stored flow (parent->x direction
        // matches), never blocks.
        int leave = -1;
        for (int x : up_v) { if (T[x].flow == 1) { leave = x; break; } }
        if (leave == -1) {
            // no blocking edge on v->lca: should not happen for assignment (flow conservation). 
            // Fall back: should not occur.
            fprintf(stderr, "no leaving arc\n"); return false;
        }
        // Update flows: decrement along v->lca up to and including leave; the edge leave->parent is removed.
        for (int x : up_v) { T[x].flow -= 1; if (x == leave) break; }
        for (int x : up_u) T[x].flow += 1;

        // Rebuild tree: detach subtree of `leave` and reattach `leave`'s subtree... 
        // For assignment with unit flow the leaving edge is on v->lca and the entering arc connects u to v.
        // New parent of the subtree: the entering arc endpoints. This is the delicate part.
        // Because unit supplies make the basis a matching plus root edges, there is a much simpler
        // representation. Abort to the simple approach if structure breaks.
        // For now, full rebuild of tree from parent pointers after reattachment.
        // Reattachment: the subtree rooted at `leave` (which contains v) should be reversed along the path
        // from leave up to v, and v attached under u via the entering arc.
        // Path from leave to v: leave, then descendants toward v. up_v lists v ... child-of-lca, and leave
        // is one of them. Nodes strictly between v and leave need parent reversal.
        // Collect path from v up to leave (inclusive):
        vector<int> path;
        for (int x : up_v) { path.push_back(x); if (x == leave) break; }
        // path: v, parent(v), ..., leave. Reverse parent links along this path.
        // detach leave from its parent
        int old_parent = T[leave].parent;
        // remove leave from old_parent's child list
        int* pp = &T[old_parent].child;
        while (*pp != -1 && *pp != leave) pp = &T[*pp].sibling;
        if (*pp == leave) *pp = T[leave].sibling;
        // reverse links: path[0]=v ... path.back()=leave
        for (int t = (int)path.size() - 1; t >= 1; --t) {
            int node = path[t];       // closer to leave
            int below = path[t - 1];  // closer to v
            T[node].parent = below;
            T[node].flow = 1;         // unit flow restored on reversed edge (direction flips, magnitude 1)
        }
        // attach v under u
        T[v].parent = u;
        T[v].sibling = T[u].child;
        T[u].child = v;
        T[v].flow = 1;
        // recompute depths, potentials, preorder, subsizes (full rebuild — acceptable if pivots are few)
        // potentials: pot[child] = pot[parent] - cost(parent->child) for a source->target edge,
        // and pot[child] = pot[parent] for root->source artificial edges (we give them cost 0 and
        // rely on reduced-cost test skipping artificial arcs since we only scan real arcs).
        vector<int> st2 = {ROOT};
        order.clear();
        while (!st2.empty()) {
            int x = st2.back(); st2.pop_back();
            order.push_back(x);
            if (x != ROOT) {
                int p = T[x].parent;
                T[x].depth = T[p].depth + 1;
                if (p == ROOT) T[x].pot = 0;
                else if (p < n && x >= n) T[x].pot = T[p].pot - C[(size_t)p * n + (x - n)];
                else if (x < n && p >= n) T[x].pot = T[p].pot + C[(size_t)x * n + (p - n)];
                else T[x].pot = T[p].pot;
            }
            for (int c = T[x].child; c != -1; c = T[c].sibling) st2.push_back(c);
        }
        fill(subsize.begin(), subsize.end(), 1);
        for (int k = (int)order.size() - 1; k >= 0; --k) {
            int x = order[k];
            if (T[x].parent != -1) subsize[T[x].parent] += subsize[x];
        }
        for (int k = 0; k < (int)order.size(); ++k) pos[order[k]] = k;
        (void)in_subtree; (void)BIG;
    }
    // read matching: each target's parent should be its matched source (unit flow)
    for (int j = 0; j < n; ++j) {
        int p = T[n + j].parent;
        if (p >= 0 && p < n) match[p] = j;
    }
    return iter < ITERMAX;
}

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 60;
    srand(1);
    vector<double> sx(n), sy(n), tx(n), ty(n);
    for (int i = 0; i < n; ++i) {
        sx[i]=rand()/(double)RAND_MAX; sy[i]=rand()/(double)RAND_MAX;
        tx[i]=rand()/(double)RAND_MAX; ty[i]=rand()/(double)RAND_MAX;
    }
    vector<double> cost((size_t)n*n);
    for (int i=0;i<n;++i) for (int j=0;j<n;++j) {
        double dx=sx[i]-tx[j], dy=sy[i]-ty[j];
        cost[(size_t)i*n+j]=sqrt(dx*dx+dy*dy);
    }
    double scale=1e6;
    vector<long long> C((size_t)n*n);
    for (size_t k=0;k<(size_t)n*n;++k) C[k]=(long long)llround(cost[k]*scale);
    vector<int> match(n,-1);
    auto t0=clk::now();
    bool ok=solve(C.data(), n, match.data());
    double ms=chrono::duration<double,milli>(clk::now()-t0).count();
    vector<char> seen(n,0); bool perm=true; double tot=0;
    for(int i=0;i<n;++i){ if(match[i]<0||match[i]>=n||seen[match[i]]) perm=false; else {seen[match[i]]=1; tot+=cost[(size_t)i*n+match[i]];} }
    printf("n=%d time=%.2f ms perm=%d cost=%.4f converged=%d\n", n, ms, (int)perm, tot, (int)ok);
}
