#include <cstdint>
#include <algorithm>
#include <climits>
#include <vector>
#include <cmath>
using namespace std;

// Bertsekas forward auction, minimization, integer costs.
// eps schedule descends by `factor` (passed as percentage, e.g. 25 => /4).
// Returns number of bids. Writes row->col assignment.
static long long auction_run(const long long* C, int n, int* rowsol, int divpct) {
    long long Cmax = 1;
    for (size_t k = 0; k < (size_t)n * n; ++k) if (C[k] > Cmax) Cmax = C[k];
    vector<long long> price(n, 0);
    vector<int> owner(n, -1);
    long long bids = 0;
    for (long long eps = Cmax / 2 + 1; ; ) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> q(n);
        for (int i = 0; i < n; ++i) q[i] = i;
        size_t head = 0;
        while (head < q.size()) {
            int i = q[head++];
            ++bids;
            const long long* row = C + (size_t)i * n;
            long long best = LLONG_MIN / 4, second = LLONG_MIN / 4;
            int jbest = 0;
            for (int j = 0; j < n; ++j) {
                long long val = -row[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            long long np_ = -row[jbest] - second + eps;
            if (np_ < price[jbest]) np_ = price[jbest];
            price[jbest] = np_;
            int prev = owner[jbest];
            owner[jbest] = i;
            if (prev != -1) q.push_back(prev);
        }
        if (eps == 1) break;
        long long next = eps * divpct / 100;
        if (next >= eps) next = eps - 1;
        if (next < 1) next = 1;
        eps = next;
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
    return bids;
}

extern "C" long long auction_solve(const double* cost, int n, int* rowsol, double scale, int divpct) {
    vector<long long> C((size_t)n * n);
    for (size_t k = 0; k < (size_t)n * n; ++k) C[k] = (long long)llround(cost[k] * scale);
    return auction_run(C.data(), n, rowsol, divpct);
}
