#include <cstdint>
#include <algorithm>
#include <climits>
#include <vector>
#include <cmath>
#include <thread>
#include <atomic>
using namespace std;

static const int THREADS = 4;
static const int BATCH = 16;

struct Partial { long long best[BATCH]; long long second[BATCH]; int jbest[BATCH]; };

static void auction_run(const long long* C, int n, int* rowsol) {
    long long Cmax = 1;
    for (size_t k = 0; k < (size_t)n * n; ++k) if (C[k] > Cmax) Cmax = C[k];
    vector<long long> price(n, 0);
    vector<int> owner(n, -1);
    Partial parts[THREADS];
    atomic<int> go{0}, done{0};
    atomic<bool> stop{false};
    int batch_rows[BATCH];
    int batch_len = 0;

    auto worker = [&](int t) {
        int seen = 0;
        while (!stop.load(memory_order_relaxed)) {
            int g = go.load(memory_order_acquire);
            if (g == seen) { this_thread::yield(); continue; }
            seen = g;
            int start = (n * t) / THREADS, end = (n * (t + 1)) / THREADS;
            for (int b = 0; b < batch_len; ++b) {
                const long long* row = C + (size_t)batch_rows[b] * n;
                long long best = LLONG_MIN/4, second = LLONG_MIN/4; int jbest = start;
                for (int j = start; j < end; ++j) {
                    long long val = -row[j] - price[j];
                    if (val > best) { second = best; best = val; jbest = j; }
                    else if (val > second) second = val;
                }
                parts[t].best[b] = best; parts[t].second[b] = second; parts[t].jbest[b] = jbest;
            }
            done.fetch_add(1, memory_order_release);
        }
    };
    vector<thread> pool;
    for (int t = 0; t < THREADS; ++t) pool.emplace_back(worker, t);

    auto flush = [&](vector<int>& q, size_t& head, long long eps) {
        done.store(0, memory_order_relaxed);
        go.fetch_add(1, memory_order_release);
        while (done.load(memory_order_acquire) < THREADS) this_thread::yield();
        for (int b = 0; b < batch_len; ++b) {
            long long best = LLONG_MIN/4, second = LLONG_MIN/4; int jbest = 0;
            for (int t = 0; t < THREADS; ++t) {
                long long bv = parts[t].best[b], sv = parts[t].second[b];
                if (bv > best) { second = max(best, max(sv, second)); best = bv; jbest = parts[t].jbest[b]; }
                else { if (bv > second) second = bv; if (sv > second) second = sv; }
            }
            int i = batch_rows[b];
            const long long* row = C + (size_t)i * n;
            long long np_ = -row[jbest] - second + eps;
            if (np_ < price[jbest]) np_ = price[jbest];
            price[jbest] = np_;
            int prev = owner[jbest];
            owner[jbest] = i;
            if (prev != -1 && prev != i) q.push_back(prev);
        }
        batch_len = 0;
    };

    for (long long eps = Cmax / 2 + 1; ; ) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> q(n);
        for (int i = 0; i < n; ++i) q[i] = i;
        size_t head = 0;
        while (head < q.size()) {
            // gather a batch of distinct rows
            bool taken[1024]; // n<=600 guard via vector
            batch_len = 0;
            while (head < q.size() && batch_len < BATCH) {
                int i = q[head++];
                bool dup = false;
                for (int b = 0; b < batch_len; ++b) if (batch_rows[b] == i) dup = true;
                if (!dup) batch_rows[batch_len++] = i;
            }
            flush(q, head, eps);
        }
        if (eps == 1) break;
        long long next = eps * 20 / 100;
        if (next >= eps) next = eps - 1;
        if (next < 1) next = 1;
        eps = next;
    }
    stop.store(true);
    for (auto& th : pool) th.join();
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
}

extern "C" void auction_solve(const double* cost, int n, int* rowsol, double scale) {
    vector<long long> C((size_t)n * n);
    for (size_t k = 0; k < (size_t)n * n; ++k) C[k] = (long long)llround(cost[k] * scale);
    auction_run(C.data(), n, rowsol);
}
