#include <cstdint>
#include <algorithm>
#include <climits>
#include <vector>
#include <cmath>
#include <pthread.h>
#include <atomic>
using namespace std;

static const int T = 6;
static long long* PRICE;
static const long long* COST;
static int N;
static int ROWS[64];
static int BLEN;
static long long B[6][64], S_[6][64];
static int JB[6][64];
static atomic<int> go_flag{0}, done_cnt{0};
static atomic<bool> stopf{false};

static void* worker(void* arg) {
    int t = (int)(intptr_t)arg;
    int seen = 0;
    while (!stopf.load(memory_order_relaxed)) {
        int g = go_flag.load(memory_order_acquire);
        if (g == seen) continue;
        seen = g;
        int start = (N * t) / T, end = (N * (t + 1)) / T;
        int bl = BLEN;
        for (int b = 0; b < bl; ++b) {
            const long long* row = COST + (size_t)ROWS[b] * N;
            long long best = LLONG_MIN/4, second = LLONG_MIN/4; int jbest = start;
            for (int j = start; j < end; ++j) {
                long long val = -row[j] - PRICE[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            B[t][b] = best; S_[t][b] = second; JB[t][b] = jbest;
        }
        done_cnt.fetch_add(1, memory_order_release);
    }
    return nullptr;
}

extern "C" void auction_solve(const double* cost, int n, int* rowsol, double scale) {
    vector<long long> C((size_t)n * n);
    long long Cmax = 1;
    for (size_t k = 0; k < (size_t)n * n; ++k) { C[k] = (long long)llround(cost[k] * scale); if (C[k] > Cmax) Cmax = C[k]; }
    vector<long long> price(n, 0);
    vector<int> owner(n, -1);
    PRICE = price.data(); COST = C.data(); N = n;
    pthread_t th[T];
    for (int t = 0; t < T; ++t) pthread_create(&th[t], nullptr, worker, (void*)(intptr_t)t);

    auto flush = [&](vector<int>& q, long long eps) {
        done_cnt.store(0, memory_order_relaxed);
        go_flag.fetch_add(1, memory_order_release);
        while (done_cnt.load(memory_order_acquire) < T) ;
        for (int b = 0; b < BLEN; ++b) {
            long long best = LLONG_MIN/4, second = LLONG_MIN/4; int jbest = 0;
            for (int t = 0; t < T; ++t) {
                long long bv = B[t][b], sv = S_[t][b];
                if (bv > best) { second = max(best, max(sv, second)); best = bv; jbest = JB[t][b]; }
                else { if (bv > second) second = bv; if (sv > second) second = sv; }
            }
            int i = ROWS[b];
            const long long* row = C.data() + (size_t)i * n;
            long long np_ = -row[jbest] - second + eps;
            if (np_ < price[jbest]) np_ = price[jbest];
            price[jbest] = np_;
            int prev = owner[jbest];
            owner[jbest] = i;
            if (prev != -1 && prev != i) q.push_back(prev);
        }
    };

    const int BATCH = 32;
    for (long long eps = Cmax / 2 + 1; ; ) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> q(n);
        for (int i = 0; i < n; ++i) q[i] = i;
        size_t head = 0;
        while (head < q.size()) {
            BLEN = 0;
            while (head < q.size() && BLEN < BATCH) {
                int i = q[head++];
                bool dup = false;
                for (int b = 0; b < BLEN; ++b) if (ROWS[b] == i) dup = true;
                if (!dup) ROWS[BLEN++] = i;
            }
            flush(q, eps);
        }
        if (eps == 1) break;
        long long next = eps / 5;
        if (next < 1) next = 1;
        eps = next;
    }
    stopf.store(true);
    // wake threads so they exit: bump flag
    go_flag.fetch_add(1, memory_order_release);
    for (int t = 0; t < T; ++t) pthread_join(th[t], nullptr);
    stopf.store(false); go_flag.store(0);
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
}
