// Compact bipartite network simplex for the assignment problem (unit supplies).
// Nodes 0..n-1 = sources, n..2n-1 = targets.
// Basis representation: each target j is a child of exactly one source (the matched one)
// OR of the root; each source is a child of the root or of a target. With unit supplies the
// basis tree has a simple alternating structure. We exploit it:
//   match[i] = target assigned to source i (flow 1 on source i -> target match[i])
//   The residual basis tree alternates. For assignment, the network simplex pivot is
//   exactly an alternating-cycle augmentation, and the reduced-cost scan is the same as
//   Hungarian. This file instead implements the classical dense network simplex with a
//   full basis tree and measures pivot throughput.
#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <climits>
using namespace std;

struct Solver {
    int n, N, ROOT;
    const long long* C;
    vector<int> parent, child, sibling, depth, preorder, pos, subsize;
    vector<long long> pot, flow;

    Solver(int n, const long long* C): n(n), N(2*n+1), ROOT(2*n), C(C),
        parent(N,-1), child(N,-1), sibling(N,-1), depth(N,0), preorder(N), pos(N), subsize(N,1),
        pot(N,0), flow(N,0) {}

    void link(int p, int c, long long f) {
        parent[c] = p; flow[c] = f;
        sibling[c] = child[p]; child[p] = c;
    }
    void init() {
        for (int i = 0; i < n; ++i) {
            link(ROOT, i, 1);
            link(i, n + i, 1);
            pot[n + i] = -C[(size_t)i * n + i];
        }
        recompute();
    }
    void recompute() {
        // DFS for preorder, depth, subtree size, potentials
        int sp = 0; 
        static thread_local vector<int> st; st.clear(); st.push_back(ROOT);
        int k = 0;
        fill(child.begin(), child.end(), -1);
        // rebuild child lists from parent
        for (int i = 0; i < N; ++i) if (i != ROOT && parent[i] != -1) {
            sibling[i] = child[parent[i]]; child[parent[i]] = i;
        }
        // iterative DFS
        vector<int> stk; stk.push_back(ROOT);
        while (!stk.empty()) {
            int u = stk.back(); stk.pop_back();
            preorder[k] = u; pos[u] = k++;
            if (u != ROOT) {
                int p = parent[u];
                depth[u] = depth[p] + 1;
                if (p == ROOT) pot[u] = 0;
                else if (p < n) pot[u] = pot[p] - C[(size_t)p * n + (u - n)];
                else pot[u] = pot[p] + C[(size_t)u * n + (p - n)];
            }
            for (int c = child[u]; c != -1; c = sibling[c]) stk.push_back(c);
        }
        fill(subsize.begin(), subsize.end(), 1);
        for (int t = N - 1; t >= 0; --t) {
            int u = preorder[t];
            if (parent[u] != -1) subsize[parent[u]] += subsize[u];
        }
    }

    bool in_sub(int node, int anc) {
        return pos[node] >= pos[anc] && pos[node] < pos[anc] + subsize[anc];
    }

    // one pivot. returns false if optimal.
    bool pivot() {
        int bi = -1, bj = -1; long long best = 0;
        for (int i = 0; i < n; ++i) {
            long long ps = pot[i];
            const long long* row = C + (size_t)i * n;
            for (int j = 0; j < n; ++j) {
                long long rc = row[j] + pot[n + j] - ps;
                if (rc < best) { best = rc; bi = i; bj = j; }
            }
        }
        if (bi < 0) return false;
        int u = bi, v = n + bj;
        // path v up to lca, find first unit-flow edge (leaving)
        int uu = u, vv = v;
        while (depth[uu] > depth[vv]) uu = parent[uu];
        while (depth[vv] > depth[uu]) vv = parent[vv];
        while (uu != vv) { uu = parent[uu]; vv = parent[vv]; }
        // leaving edge: nearest unit-flow edge on v -> lca
        int leave = -1, x = v;
        while (x != uu) { if (flow[x] == 1) { leave = x; break; } x = parent[x]; }
        if (leave < 0) return false;
        // flow updates: -1 on v->lca up to leave, +1 on u->lca
        for (x = v; x != uu; x = parent[x]) { flow[x] -= 1; if (x == leave) break; }
        for (x = u; x != uu; x = parent[x]) flow[x] += 1;
        // reattach: reverse path v..leave and hang v under u
        vector<int> path; 
        for (x = v; ; x = parent[x]) { path.push_back(x); if (x == leave) break; }
        int oldp = parent[leave];
        // detach leave from oldp child list handled by recompute
        for (int t = (int)path.size() - 1; t >= 1; --t) {
            parent[path[t]] = path[t - 1];
            flow[path[t]] = 1;
        }
        parent[v] = u; flow[v] = 1;
        recompute();
        return true;
    }

    void result(int* match) {
        for (int j = 0; j < n; ++j) {
            int p = parent[n + j];
            if (p >= 0 && p < n) match[p] = j;
        }
    }
};

int main(int argc, char** argv) {
    int n = argc > 1 ? atoi(argv[1]) : 40;
    int maxpiv = argc > 2 ? atoi(argv[2]) : 100000;
    srand(1);
    vector<double> cost((size_t)n*n);
    vector<double> sx(n),sy(n),tx(n),ty(n);
    for (int i=0;i<n;++i){sx[i]=rand()/(double)RAND_MAX;sy[i]=rand()/(double)RAND_MAX;tx[i]=rand()/(double)RAND_MAX;ty[i]=rand()/(double)RAND_MAX;}
    for (int i=0;i<n;++i) for (int j=0;j<n;++j){double dx=sx[i]-tx[j],dy=sy[i]-ty[j];cost[(size_t)i*n+j]=sqrt(dx*dx+dy*dy);} 
    vector<long long> C((size_t)n*n);
    for (size_t k=0;k<cost.size();++k) C[k]=(long long)llround(cost[k]*1e6);
    Solver s(n, C.data());
    s.init();
    auto t0 = chrono::high_resolution_clock::now();
    int piv = 0;
    while (piv < maxpiv && s.pivot()) ++piv;
    double ms = chrono::duration<double,milli>(chrono::high_resolution_clock::now()-t0).count();
    vector<int> match(n,-1); s.result(match.data());
    vector<char> seen(n,0); bool perm=true; double tot=0;
    for (int i=0;i<n;++i){ if(match[i]<0||match[i]>=n||seen[match[i]]) perm=false; else {seen[match[i]]=1; tot+=cost[(size_t)i*n+match[i]];} }
    printf("n=%d pivots=%d time=%.2f ms perm=%d cost=%.4f\n", n, piv, ms, (int)perm, tot);
}
