// Assignment network simplex with an explicit alternating basis.
// Representation (unit supplies/demands):
//   mate[i] = target matched to source i (the unique tree edge source->target with flow 1),
//             or -1 if source i is connected to the root.
//   tpar[j] = source that target j hangs from (equals the source whose mate is j, or the
//             source it connects through). For a perfect matching basis every target j has
//             tpar[j] = the matched source, and every source hangs from the root.
// A basis for assignment is a spanning tree of the bipartite graph plus root. With unit
// capacities the tree consists of the matching edges plus root edges to unmatched sources
// and "cycle-free" extra edges. We keep it general:
//   parent[node], flow[node] as before, but update the tree with a correct subtree reversal
//   and verify optimality against scipy on small n.
#include <cstdio>
#include <cstdint>
#include <vector>
#include <algorithm>
#include <chrono>
#include <cmath>
#include <cstring>
using namespace std;

static int N, ROOT, n;
static const long long* C;
static vector<int> parent, head, nexts, depth, pre, pos, sub;
static vector<long long> pot, flow;

static void rebuild_children() {
    fill(head.begin(), head.end(), -1);
    for (int i = 0; i < N; ++i) if (i != ROOT) {
        nexts[i] = head[parent[i]];
        head[parent[i]] = i;
    }
}
static void recompute() {
    rebuild_children();
    vector<int> stk; stk.push_back(ROOT);
    int k = 0;
    while (!stk.empty()) {
        int u = stk.back(); stk.pop_back();
        pre[k] = u; pos[u] = k++;
        if (u != ROOT) {
            int p = parent[u];
            depth[u] = depth[p] + 1;
            if (p == ROOT) pot[u] = 0;
            else if (p < n) pot[u] = pot[p] - C[(size_t)p * n + (u - n)];
            else            pot[u] = pot[p] + C[(size_t)u * n + (p - n)];
        } else { depth[u] = 0; pot[u] = 0; }
        for (int c = head[u]; c != -1; c = nexts[c]) stk.push_back(c);
    }
    fill(sub.begin(), sub.end(), 1);
    for (int t = N - 1; t >= 1; --t) sub[parent[pre[t]]] += sub[pre[t]];
}

static bool pivot() {
    int bi = -1, bj = -1; long long best = 0;
    for (int i = 0; i < n; ++i) {
        long long ps = pot[i];
        const long long* row = C + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            long long rc = row[j] - ps + pot[n + j];
            if (rc < best) { best = rc; bi = i; bj = j; }
        }
    }
    if (bi < 0) return false;
    int u = bi, v = n + bj;
    int uu = u, vv = v;
    while (depth[uu] > depth[vv]) uu = parent[uu];
    while (depth[vv] > depth[uu]) vv = parent[vv];
    while (uu != vv) { uu = parent[uu]; vv = parent[vv]; }
    int lca = uu;
    // orientation: adding flow on arc u->v. The apex (lca) splits the cycle.
    // Flow change of +1 along the cycle in the direction u -> v -> ... -> lca -> ... -> u.
    // On the segment from v up to lca, stored flow (parent->node) opposes the cycle direction
    // when the tree edge is traversed upward, so stored flow decreases and can block.
    // On the segment from u up to lca, stored flow increases.
    int leave = -1;
    for (int x = v; x != lca; x = parent[x]) if (flow[x] <= 1) { leave = x; break; }
    if (leave < 0) { fprintf(stderr, "no leave\n"); return false; }
    for (int x = v; x != lca; x = parent[x]) { flow[x] -= 1; if (x == leave) break; }
    for (int x = u; x != lca; x = parent[x]) flow[x] += 1;

    // Reverse the path from `leave` down to `v` and attach v to u.
    // path from v up to leave: v = p0, p1, ..., leave
    vector<int> path;
    for (int x = v; ; x = parent[x]) { path.push_back(x); if (x == leave) break; }
    // detach leave from its old parent (parent pointers only; children rebuilt later)
    for (int t = (int)path.size() - 1; t >= 1; --t) {
        int node = path[t];
        int below = path[t - 1];
        parent[node] = below;
        flow[node] = 1; // reversed edge carries the residual unit
    }
    parent[v] = u;
    flow[v] = 1;
    recompute();
    return true;
}

int main(int argc, char** argv) {
    n = argc > 1 ? atoi(argv[1]) : 30;
    N = 2 * n + 1; ROOT = 2 * n;
    srand(1);
    vector<double> cost((size_t)n * n), sx(n), sy(n), tx(n), ty(n);
    for (int i = 0; i < n; ++i) { sx[i]=rand()/(double)RAND_MAX; sy[i]=rand()/(double)RAND_MAX; tx[i]=rand()/(double)RAND_MAX; ty[i]=rand()/(double)RAND_MAX; }
    for (int i = 0; i < n; ++i) for (int j = 0; j < n; ++j) { double dx=sx[i]-tx[j], dy=sy[i]-ty[j]; cost[(size_t)i*n+j]=sqrt(dx*dx+dy*dy); }
    vector<long long> CC((size_t)n*n);
    for (size_t k = 0; k < cost.size(); ++k) CC[k] = (long long)llround(cost[k]*1e6);
    C = CC.data();
    parent.assign(N,-1); head.assign(N,-1); nexts.assign(N,-1); depth.assign(N,0);
    pre.assign(N,0); pos.assign(N,0); sub.assign(N,1); pot.assign(N,0); flow.assign(N,0);
    for (int i = 0; i < n; ++i) { parent[i] = ROOT; flow[i] = 1; parent[n+i] = i; flow[n+i] = 1; }
    recompute();
    auto t0 = chrono::high_resolution_clock::now();
    int piv = 0; while (pivot()) ++piv;
    double ms = chrono::duration<double,milli>(chrono::high_resolution_clock::now()-t0).count();
    vector<int> match(n,-1);
    for (int j = 0; j < n; ++j) { int p = parent[n+j]; if (p>=0 && p<n) match[p] = j; }
    vector<char> seen(n,0); bool perm = true; double tot = 0;
    for (int i = 0; i < n; ++i) { if (match[i]<0||match[i]>=n||seen[match[i]]) perm=false; else { seen[match[i]]=1; tot += cost[(size_t)i*n+match[i]]; } }
    printf("n=%d pivots=%d time=%.2f ms perm=%d cost=%.4f\n", n, piv, ms, (int)perm, tot);
}
