using namespace std;

// Epsilon-scaling auction that KEEPS the assignment between phases.
// At phase start, every column is owned. A row is "happy" if its owned object's
// profit is within eps of the best. Unhappy rows bid and may displace others.
// This is the standard Gauss-Seidel auction with epsilon scaling (Bertsekas).
static void auction(const long long* C, int n, int* rowsol) {
    long long Cmax = 1;
    for (size_t k = 0; k < (size_t)n*n; ++k) if (C[k] > Cmax) Cmax = C[k];
    vector<long long> price(n, 0);
    vector<int> owner(n, -1);

    for (long long eps = Cmax / 2 + 1; ; ) {
        vector<int> q;
        q.reserve(n);
        vector<char> inq(n, 0);
        for (int i = 0; i < n; ++i) {
            // a row is unassigned if no column owns it
            bool assigned = false;
            q.push_back(i); // re-check all at phase start; displaced-only thereafter
        }
        // Actually restarting the queue with all rows each phase defeats the purpose.
        // Instead: rows whose current object is no longer eps-best must rebid.
        // We detect that implicitly by bidding only for rows not owning their best.
        // Simpler correct variant: queue holds unassigned rows only, and we seed it
        // with rows that are unassigned. Assignment persists, so only displaced rows
        // plus initially unassigned rows are processed. At phase start nobody is
        // unassigned (after first phase). The eps decrease makes some assignments
        // suboptimal but they remain assigned. We must re-bid rows that are not
        // eps-optimal. Identify them with one scan, then only those rebid.
        q.clear();
        vector<char> assigned_row(n, 0);
        for (int j = 0; j < n; ++j) if (owner[j] != -1) assigned_row[owner[j]] = 1;
        for (int i = 0; i < n; ++i) if (!assigned_row[i]) q.push_back(i);
        if (q.empty()) {
            // all assigned: find rows that are not eps-happy and release them
            for (int i = 0; i < n; ++i) {
                const long long* row = C + (size_t)i * n;
                long long best = LLONG_MIN/4; int jbest = 0;
                for (int j = 0; j < n; ++j) {
                    long long val = -row[j] - price[j];
                    if (val > best) { best = val; jbest = j; }
                }
                int owned = -1;
                // find column owned by i
                // (store inverse)
            }
        }
        size_t head = 0;
        while (head < q.size()) {
            int i = q[head++];
            const long long* row = C + (size_t)i * n;
            long long best = LLONG_MIN/4, second = LLONG_MIN/4; int jbest = 0;
            for (int j = 0; j < n; ++j) {
                long long val = -row[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            long long np_ = -row[jbest] - second + eps;
            if (np_ < price[jbest]) np_ = price[jbest];
            price[jbest] = np_;
            int prev = owner[jbest];
            owner[jbest] = i;
            if (prev != -1 && prev != i) q.push_back(prev);
        }
        if (eps == 1) break;
        long long next = eps / 5; if (next < 1) next = 1; eps = next;
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
}

// Version with persistent assignment AND selective rebidding.
static void auction2(const long long* C, int n, int* rowsol) {
    long long Cmax = 1;
    for (size_t k = 0; k < (size_t)n*n; ++k) if (C[k] > Cmax) Cmax = C[k];
    vector<long long> price(n, 0);
    vector<int> owner(n, -1), assign(n, -1);

    for (long long eps = Cmax / 2 + 1; ; ) {
        vector<int> q; q.reserve(2 * n);
        for (int i = 0; i < n; ++i) if (assign[i] == -1) q.push_back(i);
        // release rows that are not eps-optimal for their current assignment
        for (int i = 0; i < n; ++i) {
            if (assign[i] == -1) continue;
            const long long* row = C + (size_t)i * n;
            long long my = -row[assign[i]] - price[assign[i]];
            long long best = my;
            for (int j = 0; j < n; ++j) {
                long long val = -row[j] - price[j];
                if (val > best) best = val;
            }
            if (best > my + eps) {
                // not eps-happy: release and rebid
                owner[assign[i]] = -1;
                assign[i] = -1;
                q.push_back(i);
            }
        }
        size_t head = 0;
        while (head < q.size()) {
            int i = q[head++];
            const long long* row = C + (size_t)i * n;
            long long best = LLONG_MIN/4, second = LLONG_MIN/4; int jbest = 0;
            for (int j = 0; j < n; ++j) {
                long long val = -row[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            // already happy enough? (profit gap <= eps) -> just take it, price unchanged
            if (best - second <= eps && owner[jbest] == -1) {
                owner[jbest] = i; assign[i] = jbest; continue;
            }
            long long np_ = -row[jbest] - second + eps;
            if (np_ < price[jbest]) np_ = price[jbest];
            price[jbest] = np_;
            int prev = owner[jbest];
            owner[jbest] = i; assign[i] = jbest;
            if (prev != -1 && prev != i) { assign[prev] = -1; q.push_back(prev); }
        }
        if (eps == 1) break;
        long long next = eps / 5; if (next < 1) next = 1; eps = next;
    }
    for (int i = 0; i < n; ++i) rowsol[i] = assign[i];
}

extern "C" void auction_solve(const double* cost, int n, int* rowsol, double scale) {
    vector<long long> C((size_t)n*n);
    for (size_t k = 0; k < (size_t)n*n; ++k) C[k] = (long long)llround(cost[k]*scale);
    auction2(C.data(), n, rowsol);
}
