#include <cstdint>
#include <algorithm>
#include <climits>
#include <vector>
#include <cmath>
#include <immintrin.h>
using namespace std;

// AVX2 two-best scan: process 4 columns at a time with int64 arithmetic.
static inline void scan_avx(const long long* row, const long long* price, int n,
                            long long& best, long long& second, int& jbest) {
    best = LLONG_MIN/4; second = LLONG_MIN/4; jbest = 0;
    int j = 0;
    for (; j + 3 < n; j += 4) {
        long long vals[4];
        __m256i r = _mm256_loadu_si256((const __m256i*)(row + j));
        __m256i p = _mm256_loadu_si256((const __m256i*)(price + j));
        __m256i v = _mm256_sub_epi64(_mm256_sub_epi64(_mm256_setzero_si256(), r), p);
        _mm256_storeu_si256((__m256i*)vals, v);
        for (int t = 0; t < 4; ++t) {
            long long val = vals[t];
            if (val > best) { second = best; best = val; jbest = j + t; }
            else if (val > second) second = val;
        }
    }
    for (; j < n; ++j) {
        long long val = -row[j] - price[j];
        if (val > best) { second = best; best = val; jbest = j; }
        else if (val > second) second = val;
    }
}

