#include <cstdint>
#include <algorithm>
#include <climits>
#include <vector>
#include <cmath>
using namespace std;

// Solve a batch of B rows simultaneously, scanning columns in blocks so the price
// block stays in cache and is reused across the B rows.
static void auction(const long long* C, int n, int* rowsol) {
    const int B = 8;
    long long Cmax = 1;
    for (size_t k = 0; k < (size_t)n*n; ++k) if (C[k] > Cmax) Cmax = C[k];
    vector<long long> price(n, 0);
    vector<int> owner(n, -1);

    for (long long eps = Cmax / 2 + 1; ; ) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> q(n);
        for (int i = 0; i < n; ++i) q[i] = i;
        size_t head = 0;
        while (head < q.size()) {
            int rows[B]; bool alive[B];
            int cnt = 0;
            while (head < q.size() && cnt < B) {
                int i = q[head++];
                bool dup = false;
                for (int t = 0; t < cnt; ++t) if (rows[t] == i) dup = true;
                if (!dup) { rows[cnt] = i; alive[cnt] = true; ++cnt; }
            }
            long long best[B], second[B]; int jbest[B];
            for (int t = 0; t < cnt; ++t) { best[t] = LLONG_MIN/4; second[t] = LLONG_MIN/4; jbest[t] = 0; }
            for (int j = 0; j < n; ++j) {
                long long pj = price[j];
                for (int t = 0; t < cnt; ++t) {
                    long long val = -C[(size_t)rows[t]*n + j] - pj;
                    if (val > best[t]) { second[t] = best[t]; best[t] = val; jbest[t] = j; }
                    else if (val > second[t]) second[t] = val;
                }
            }
            for (int t = 0; t < cnt; ++t) {
                int i = rows[t]; int jb = jbest[t];
                long long np_ = -C[(size_t)i*n + jb] - second[t] + eps;
                if (np_ < price[jb]) np_ = price[jb];
                price[jb] = np_;
                int prev = owner[jb];
                owner[jb] = i;
                if (prev != -1 && prev != i) q.push_back(prev);
            }
        }
        if (eps == 1) break;
        long long next = eps / 5; if (next < 1) next = 1; eps = next;
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
}

extern "C" void auction_solve(const double* cost, int n, int* rowsol, double scale) {
    vector<long long> C((size_t)n*n);
    for (size_t k = 0; k < (size_t)n*n; ++k) C[k] = (long long)llround(cost[k]*scale);
    auction(C.data(), n, rowsol);
}
