#include <cstdint>
#include <algorithm>
#include <climits>
#include <vector>
#include <cmath>
using namespace std;

// Auction over a candidate list (k nearest per row), with a correctness fallback:
// after the sparse auction, run a final eps=1 phase but each row first checks its
// candidate list; only rows whose best candidate is beaten by some outside column
// (detected by a sampled check) get a full scan. To guarantee exactness we do one
// full verification pass at the end: any row not eps-optimal is re-queued for a
// full-scan bid. If the candidate graph already holds the optimum this pass finds
// nothing and costs one scan per row — still O(n^2). So instead, verification must
// be cheaper than a full scan.
//
// Hybrid: run sparse auction, then verify with a FULL but vectorized single pass
// that only re-bids violating rows. Measure how many violate.
static void knn(const double* cost, int n, int k, vector<int>& ind) {
    ind.resize((size_t)n * k);
    vector<int> idx(n);
    for (int i = 0; i < n; ++i) {
        const double* row = cost + (size_t)i * n;
        iota(idx.begin(), idx.end(), 0);
        nth_element(idx.begin(), idx.begin()+k, idx.end(), [&](int a, int b){ return row[a] < row[b]; });
        for (int t = 0; t < k; ++t) ind[(size_t)i*k + t] = idx[t];
    }
}

struct Stats { long long bids_sparse, bids_full; int phases; };

static void auction_hybrid(const long long* C, const vector<int>& ind, int n, int k, int* rowsol, Stats& st) {
    long long Cmax = 1;
    for (size_t t = 0; t < (size_t)n*k; ++t) {
        long long v = C[(size_t)(t/k)*n + ind[t]];
        if (v > Cmax) Cmax = v;
    }
    vector<long long> price(n, 0);
    vector<int> owner(n, -1);
    st = {0,0,0};

    auto bid_sparse = [&](int i, long long eps, vector<int>& q) {
        const int* ci = ind.data() + (size_t)i*k;
        long long best = LLONG_MIN/4, second = LLONG_MIN/4; int jbest = ci[0];
        for (int t = 0; t < k; ++t) {
            int j = ci[t];
            long long val = -C[(size_t)i*n + j] - price[j];
            if (val > best) { second = best; best = val; jbest = j; }
            else if (val > second) second = val;
        }
        long long np_ = -C[(size_t)i*n + jbest] - second + eps;
        if (np_ < price[jbest]) np_ = price[jbest];
        price[jbest] = np_;
        int prev = owner[jbest]; owner[jbest] = i;
        if (prev != -1 && prev != i) q.push_back(prev);
        st.bids_sparse++;
    };

    for (long long eps = Cmax/2 + 1; ; ) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> q(n); iota(q.begin(), q.end(), 0);
        size_t head = 0;
        while (head < q.size()) bid_sparse(q[head++], eps, q);
        st.phases++;
        if (eps == 1) break;
        long long next = eps/5; if (next < 1) next = 1; eps = next;
    }
    // verification: full scan, rebid violating rows at eps=1 until stable
    bool changed = true; int guard = 0;
    while (changed && guard++ < 50) {
        changed = false;
        for (int i = 0; i < n; ++i) {
            const long long* row = C + (size_t)i*n;
            long long best = LLONG_MIN/4, second = LLONG_MIN/4; int jbest = 0;
            for (int j = 0; j < n; ++j) {
                long long val = -row[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            st.bids_full++;
            int cur = -1; for (int j = 0; j < n; ++j) if (owner[j]==i) { cur = j; break; }
            if (cur == jbest && best - second <= 1) continue;
            long long np_ = -row[jbest] - second + 1;
            if (np_ < price[jbest]) np_ = price[jbest];
            if (owner[jbest] == i && price[jbest] == np_) continue;
            price[jbest] = np_;
            int prev = owner[jbest]; owner[jbest] = i;
            if (prev != -1 && prev != i) { changed = true; }
            changed = true;
        }
    }
    for (int j = 0; j < n; ++j) if (owner[j] != -1) rowsol[owner[j]] = j;
}

extern "C" void auction_solve(const double* cost, int n, int k, int* rowsol, double scale) {
    vector<int> ind; knn(cost, n, k, ind);
    vector<long long> C((size_t)n*n);
    for (size_t t = 0; t < (size_t)n*n; ++t) C[t] = (long long)llround(cost[t]*scale);
    Stats st; auction_hybrid(C.data(), ind, n, k, rowsol, st);
    fprintf(stderr, "k=%d sparse_bids=%lld full_bids=%lld phases=%d\n", k, st.bids_sparse, st.bids_full, st.phases);
}
