// Cost-scaling assignment algorithm (Goldberg / Kennedy style), dense.
// Integer costs. Uses epsilon scaling with a push of admissible arcs and a
// global price update (refine). This is the "cost scaling" method:
//   while eps >= 1:
//     while there is a source with residual demand:
//       find admissible arc (reduced cost < eps) to an unsaturated target, push;
//       if a source has no admissible arc, raise its potential (relabel) so one appears.
// Potentials maintained so all reduced costs stay nonnegative.
#include <cstdint>
#include <vector>
#include <algorithm>
#include <climits>
#include <cstdio>
#include <cmath>
using namespace std;

// Reduced cost of source i -> target j: C[i,j] - alpha[i] - beta[j], kept >= 0.
// We store alpha for sources and beta for targets.
static bool solve(const long long* C, int n, int* rowsol) {
    vector<long long> alpha(n, 0), beta(n, 0);
    vector<int> mate(n, -1);     // source -> target
    vector<int> mate_of(n, -1);  // target -> source

    long long Cmax = 1;
    for (size_t k = 0; k < (size_t)n*n; ++k) if (C[k] > Cmax) Cmax = C[k];

    for (long long eps = Cmax; eps >= 1; ) {
        // scale: refine to eps-optimality. Reset matching (prices carry over).
        fill(mate.begin(), mate.end(), -1);
        fill(mate_of.begin(), mate_of.end(), -1);
        vector<int> unassigned;
        for (int i = 0; i < n; ++i) unassigned.push_back(i);
        size_t head = 0;
        while (head < unassigned.size()) {
            int i = unassigned[head++];
            // find admissible target: C[i,j] - alpha[i] - beta[j] < eps, prefer free
            int jbest = -1; long long best_rc = LLONG_MAX;
            const long long* row = C + (size_t)i*n;
            long long ai = alpha[i];
            for (int j = 0; j < n; ++j) {
                long long rc = row[j] - ai - beta[j];
                if (rc < eps && rc < best_rc) { best_rc = rc; jbest = j; if (rc <= 0 && mate_of[j] == -1) break; }
            }
            if (jbest == -1) {
                // relabel source: raise alpha so the smallest reduced cost becomes 0
                long long mn = LLONG_MAX;
                for (int j = 0; j < n; ++j) mn = min(mn, row[j] - beta[j]);
                alpha[i] = mn; // rc' = row - mn - beta >= 0, min is 0
                // requeue
                unassigned.push_back(i);
                continue;
            }
            int prev = mate_of[jbest];
            mate[i] = jbest; mate_of[jbest] = i;
            if (prev != -1 && prev != i) { mate[prev] = -1; unassigned.push_back(prev); }
        }
        // price update to keep dual feasible: beta[j] = min_i (C[i,j] - alpha[i])
        for (int j = 0; j < n; ++j) {
            long long mn = LLONG_MAX;
            for (int i = 0; i < n; ++i) mn = min(mn, C[(size_t)i*n + j] - alpha[i]);
            beta[j] = mn;
        }
        if (eps == 1) break;
        eps = max(1LL, eps / 2);
    }
    for (int i = 0; i < n; ++i) rowsol[i] = mate[i];
    return true;
}

extern "C" void cs_solve(const double* cost, int n, int* rowsol, double scale) {
    vector<long long> C((size_t)n*n);
    for (size_t k = 0; k < (size_t)n*n; ++k) C[k] = (long long)llround(cost[k]*scale);
    solve(C.data(), n, rowsol);
}
