#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cfloat>
using namespace std;

// Double-precision epsilon-scaling auction. No integer conversion.
// eps starts at (max-min)/2 and shrinks by `shrink` until below tol/n.
static void auction(const double* C, int n, int* rowsol, double shrink, double tol) {
    double Cmax = -DBL_MAX, Cmin = DBL_MAX;
    for (size_t k = 0; k < (size_t)n*n; ++k) { Cmax = max(Cmax, C[k]); Cmin = min(Cmin, C[k]); }
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1);
    double eps = (Cmax - Cmin) / 2.0 + tol;
    const double eps_min = tol / n;
    for (;;) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> q(n);
        for (int i = 0; i < n; ++i) q[i] = i;
        size_t head = 0;
        while (head < q.size()) {
            int i = q[head++];
            const double* row = C + (size_t)i*n;
            double best = -DBL_MAX, second = -DBL_MAX; int jbest = 0;
            for (int j = 0; j < n; ++j) {
                double val = -row[j] - price[j];
                if (val > best) { second = best; best = val; jbest = j; }
                else if (val > second) second = val;
            }
            double np_ = -row[jbest] - second + eps;
            if (np_ < price[jbest]) np_ = price[jbest];
            price[jbest] = np_;
            int prev = owner[jbest];
            owner[jbest] = i;
            if (prev != -1 && prev != i) q.push_back(prev);
        }
        if (eps <= eps_min) break;
        eps = max(eps_min, eps * shrink);
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
}

extern "C" void auction_solve(const double* cost, int n, int* rowsol, double shrink, double tol) {
    auction(cost, n, rowsol, shrink, tol);
}
