#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cfloat>
#include <immintrin.h>
using namespace std;

// Float64 auction. Inner scan keeps 4 independent running best/second pairs
// (one per AVX lane) and merges once per row, removing the loop-carried
// dependency. Processes ROWS rows per column sweep so the price vector is
// loaded once and reused.
static const int ROWS = 4;

static void auction(const double* C, int n, int* rowsol) {
    double Cmax = -DBL_MAX, Cmin = DBL_MAX;
    for (size_t k = 0; k < (size_t)n * n; ++k) { Cmax = max(Cmax, C[k]); Cmin = min(Cmin, C[k]); }
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1);
    double eps = (Cmax - Cmin) / 2.0 + 1e-9;
    const double eps_min = 1e-12;

    auto scan_row = [&](int i, double& best, double& second, int& jbest) {
        const double* row = C + (size_t)i * n;
        __m256d b = _mm256_set1_pd(-DBL_MAX);
        __m256d s = _mm256_set1_pd(-DBL_MAX);
        __m256d jb = _mm256_setzero_pd();
        int j = 0;
        for (; j + 3 < n; j += 4) {
            __m256d r = _mm256_loadu_pd(row + j);
            __m256d p = _mm256_loadu_pd(price.data() + j);
            __m256d val = _mm256_sub_pd(_mm256_sub_pd(_mm256_setzero_pd(), r), p);
            __m256d idx = _mm256_set_pd(j + 3, j + 2, j + 1, j);
            // val > b  -> update second=b, best=val, jbest=idx
            __m256d gt = _mm256_cmp_pd(val, b, _CMP_GT_OQ);
            s = _mm256_blendv_pd(s, b, gt);
            b = _mm256_blendv_pd(b, val, gt);
            jb = _mm256_blendv_pd(jb, idx, gt);
            // val > s and not already best: second = val where val>s and !gt
            __m256d gts = _mm256_andnot_pd(gt, _mm256_cmp_pd(val, s, _CMP_GT_OQ));
            s = _mm256_blendv_pd(s, val, gts);
        }
        // merge lanes
        alignas(32) double bv[4], sv[4], iv[4];
        _mm256_store_pd(bv, b); _mm256_store_pd(sv, s); _mm256_store_pd(iv, jb);
        best = -DBL_MAX; second = -DBL_MAX; jbest = 0;
        for (int t = 0; t < 4; ++t) {
            if (bv[t] > best) { second = max(best, max(sv[t], second)); best = bv[t]; jbest = (int)iv[t]; }
            else { if (bv[t] > second) second = bv[t]; if (sv[t] > second) second = sv[t]; }
        }
        for (; j < n; ++j) {
            double val = -row[j] - price[j];
            if (val > best) { second = best; best = val; jbest = j; }
            else if (val > second) second = val;
        }
    };

    for (;;) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> q(n);
        for (int i = 0; i < n; ++i) q[i] = i;
        size_t head = 0;
        while (head < q.size()) {
            int i = q[head++];
            double best, second; int jbest;
            scan_row(i, best, second, jbest);
            const double* row = C + (size_t)i * n;
            double np_ = -row[jbest] - second + eps;
            if (np_ < price[jbest]) np_ = price[jbest];
            price[jbest] = np_;
            int prev = owner[jbest];
            owner[jbest] = i;
            if (prev != -1 && prev != i) q.push_back(prev);
        }
        if (eps <= eps_min) break;
        double next = eps * 0.25;
        if (next < eps_min) next = eps_min;
        eps = next;
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
}

extern "C" void auction_solve(const double* cost, int n, int* rowsol) { auction(cost, n, rowsol); }
