#include <cstdint>
#include <vector>
#include <algorithm>
#include <cmath>
#include <cfloat>
#include <cstring>
using namespace std;

// Multi-row branchless auction scan. Processes B rows per column sweep with
// independent dependency chains so the CPU overlaps them.
template <int B>
static void scan_batch(const double* C, int n, const double* price, const int* rows,
                       double* best, double* second, int* jbest) {
    const double* rp[B];
    for (int t = 0; t < B; ++t) {
        rp[t] = C + (size_t)rows[t] * n;
        best[t] = -DBL_MAX; second[t] = -DBL_MAX; jbest[t] = 0;
    }
    for (int j = 0; j < n; ++j) {
        double pj = price[j];
        #pragma unroll
        for (int t = 0; t < B; ++t) {
            double val = -rp[t][j] - pj;
            bool gt = val > best[t];
            double ns = val > second[t] ? val : second[t];
            second[t] = gt ? best[t] : ns;
            best[t] = gt ? val : best[t];
            jbest[t] = gt ? j : jbest[t];
        }
    }
}

static void auction(const double* C, int n, int* rowsol) {
    const int B = 8;
    double Cmax = -DBL_MAX, Cmin = DBL_MAX;
    for (size_t k = 0; k < (size_t)n * n; ++k) { if (C[k] > Cmax) Cmax = C[k]; if (C[k] < Cmin) Cmin = C[k]; }
    vector<double> price(n, 0.0);
    vector<int> owner(n, -1);
    double eps = (Cmax - Cmin) / 2.0 + 1e-9;
    const double eps_min = 1e-12;

    for (;;) {
        fill(owner.begin(), owner.end(), -1);
        vector<int> q(n);
        for (int i = 0; i < n; ++i) q[i] = i;
        size_t head = 0;
        while (head < q.size()) {
            int rows[B]; int cnt = 0;
            while (head < q.size() && cnt < B) {
                int i = q[head++];
                bool dup = false;
                for (int t = 0; t < cnt; ++t) if (rows[t] == i) dup = true;
                if (!dup) rows[cnt++] = i;
            }
            // pad to B with duplicates of rows[0] (results ignored)
            for (int t = cnt; t < B; ++t) rows[t] = rows[0];
            double best[B], second[B]; int jbest[B];
            scan_batch<B>(C, n, price.data(), rows, best, second, jbest);
            for (int t = 0; t < cnt; ++t) {
                int i = rows[t]; int jb = jbest[t];
                double np_ = -C[(size_t)i * n + jb] - second[t] + eps;
                if (np_ < price[jb]) np_ = price[jb];
                price[jb] = np_;
                int prev = owner[jb];
                owner[jb] = i;
                if (prev != -1 && prev != i) q.push_back(prev);
            }
        }
        if (eps <= eps_min) break;
        double next = eps * 0.25;
        if (next < eps_min) next = eps_min;
        eps = next;
    }
    for (int j = 0; j < n; ++j) rowsol[owner[j]] = j;
}

extern "C" void auction_solve(const double* cost, int n, int* rowsol) { auction(cost, n, rowsol); }
