static bool pivot() {
    int bi = -1, bj = -1; long long best = 0;
    for (int i = 0; i < n; ++i) {
        long long ps = pot[i];
        const long long* row = C + (size_t)i * n;
        for (int j = 0; j < n; ++j) {
            long long rc = row[j] - ps + pot[n + j];
            if (rc < best) { best = rc; bi = i; bj = j; }
        }
    }
    if (bi < 0) return false;
    int u = bi, v = n + bj;
    int uu = u, vv = v;
    while (depth[uu] > depth[vv]) uu = parent[uu];
    while (depth[vv] > depth[uu]) vv = parent[vv];
    while (uu != vv) { uu = parent[uu]; vv = parent[vv]; }
    int lca = uu;
    // orientation: adding flow on arc u->v. The apex (lca) splits the cycle.
    // Flow change of +1 along the cycle in the direction u -> v -> ... -> lca -> ... -> u.
    // On the segment from v up to lca, stored flow (parent->node) opposes the cycle direction
    // when the tree edge is traversed upward, so stored flow decreases and can block.
    // On the segment from u up to lca, stored flow increases.
    int leave = -1;
    for (int x = v; x != lca; x = parent[x]) if (flow[x] <= 1) { leave = x; break; }
    if (leave < 0) { fprintf(stderr, "no leave\n"); return false; }
    for (int x = v; x != lca; x = parent[x]) { flow[x] -= 1; if (x == leave) break; }
    for (int x = u; x != lca; x = parent[x]) flow[x] += 1;

    // Reverse the path from `leave` down to `v` and attach v to u.
    // path from v up to leave: v = p0, p1, ..., leave
    vector<int> path;
    for (int x = v; ; x = parent[x]) { path.push_back(x); if (x == leave) break; }
    // detach leave from its old parent (parent pointers only; children rebuilt later)
    for (int t = (int)path.size() - 1; t >= 1; --t) {
        int node = path[t];
        int below = path[t - 1];
        parent[node] = below;
        flow[node] = 1; // reversed edge carries the residual unit
    }
    parent[v] = u;
    flow[v] = 1;
    recompute();
    return true;
}

